    vector<vector<long long>> c(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> c[i][j];
        }
    }

    sort(c.begin(), c.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[1] < y[1]; });
    priority_queue<long long> heap;
    long long days = 0;
    for (const vector<long long>& course : c) {
        days += course[0];
        heap.push(course[0]);
        if (days > course[1]) {
