import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] c = new long[(int) n][2];
        for (int i = 0; i < c.length; i++) {
            for (int j = 0; j < c[i].length; j++) {
                c[i][j] = Long.parseLong(next());
            }
        }

        Arrays.sort(c, (x, y) -> Long.compare(x[1], y[1]));
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        long days = 0;
        for (long[] course : c) {
            days += course[0];
            heap.add(course[0]);
            if (days > course[1]) days -= heap.poll();
        }
        System.out.println(heap.size());
    }
}
